-- 120_staff_calendar_holidays_seed.sql
-- Staff Calendar: the Kenyan public holidays for the next 10 years, 2025 to 2034 (111 rows). The dates were worked out in code (app/v1/services/StaffHolidays.php):
-- the fixed dates (New Year's Day, Labour Day, Madaraka Day, Mazingira Day, Mashujaa Day, Jamhuri Day, Christmas Day, Boxing Day), Good Friday and Easter Monday from Easter, and an EXPECTED
-- date for Eid ul-Fitr (is_confirmed = 0, shown as Expected, to be confirmed, until the super admin sets the announced date). A holiday that falls on a Sunday is kept on the Monday after it
-- (the note says so). Safe to run twice and on the live site: a row is added only when its source_key is not there yet, so nothing is duplicated and a holiday the super admin changed keeps its changes.
INSERT INTO staff_calendar_holidays (holiday_date, name, kind, is_confirmed, base_date, note, source_key)
